script.setup:
// three-mesh-bvh builds a bounding volume hierarchy over a 200k-triangle knot so
// thousands of rays per frame can be cast against it; Three.js draws the beams.
const THREE_URL = "https://esm.sh/three@0.186.0";
const mod = await ctx.utils.import(THREE_URL);
const THREE = mod.default ?? mod;
// ?deps pins the library to the same three build, so both share one module instance.
const bvhMod = await ctx.utils.import("https://esm.sh/three-mesh-bvh@0.9.15?deps=three@0.186.0");
const { MeshBVH } = bvhMod.default ?? bvhMod;
const renderer = new THREE.WebGLRenderer({ canvas: ctx.canvas, context: ctx.gl, antialias: true });
renderer.setPixelRatio(1);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x040509);
const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
// A lumpy torus knot: dense enough that brute-force raycasting would crawl.
const geometry = new THREE.TorusKnotGeometry(1.2, 0.42, 900, 112, 2, 3);
const pos = geometry.attributes.position, nrm = geometry.attributes.normal, v = new THREE.Vector3(), n = new THREE.Vector3();
for (let i = 0; i < pos.count; i++) {
  v.fromBufferAttribute(pos, i); n.fromBufferAttribute(nrm, i);
  const bump = 0.06 * Math.sin(v.x * 7) * Math.sin(v.y * 7) * Math.sin(v.z * 7);
  v.addScaledVector(n, bump); pos.setXYZ(i, v.x, v.y, v.z);
}
geometry.computeVertexNormals();
const t0 = performance.now();
const bvh = new MeshBVH(geometry);
ctx.publish("bvh build ms", Math.round(performance.now() - t0));
ctx.publish("triangles", geometry.index.count / 3);
const knot = new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({ color: 0x2c3247, metalness: 0.2, roughness: 0.55 }));
scene.add(knot);
scene.add(new THREE.HemisphereLight(0x8899cc, 0x221a10, 1.2));
const sun = new THREE.DirectionalLight(0xffffff, 1.2); sun.position.set(3, 5, 4); scene.add(sun);
const MAX = 20000;
const linePos = new Float32Array(MAX * 6), lineCol = new Float32Array(MAX * 6);
const lineGeo = new THREE.BufferGeometry();
lineGeo.setAttribute("position", new THREE.BufferAttribute(linePos, 3).setUsage(THREE.DynamicDrawUsage));
lineGeo.setAttribute("color", new THREE.BufferAttribute(lineCol, 3).setUsage(THREE.DynamicDrawUsage));
const lines = new THREE.LineSegments(lineGeo, new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
lines.frustumCulled = false;
scene.add(lines);
// Hits are kept in a ring buffer in the knot's own space, so the paint sticks to it and fades.
const HITS = 120000;
const hitPos = new Float32Array(HITS * 3), hitCol = new Float32Array(HITS * 3);
const hitGeo = new THREE.BufferGeometry();
hitGeo.setAttribute("position", new THREE.BufferAttribute(hitPos, 3).setUsage(THREE.DynamicDrawUsage));
hitGeo.setAttribute("color", new THREE.BufferAttribute(hitCol, 3).setUsage(THREE.DynamicDrawUsage));
const hits = new THREE.Points(hitGeo, new THREE.PointsMaterial({ size: 0.03, vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
hits.frustumCulled = false;
knot.add(hits);
Object.assign(ctx.state, { THREE, renderer, scene, camera, knot, bvh, lines, hits, linePos, lineCol, hitPos, hitCol, MAX, HITS, head: 0, size: [0, 0],
  ray: new THREE.Ray(), inv: new THREE.Matrix4(), tmp: new THREE.Vector3(), colors: [new THREE.Color(), new THREE.Color(), new THREE.Color()],
  orbit: ctx.utils.createOrbitCamera({ distance: 8.2, theta: 1.2, phi: 1.0 }) });

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution, { THREE } = s;
if (s.size[0] !== w || s.size[1] !== h) { s.size = [w, h]; s.renderer.setSize(w, h, false); s.camera.aspect = w / h; s.camera.updateProjectionMatrix(); }
s.orbit.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
s.camera.position.fromArray(s.orbit.getEye());
s.camera.lookAt(0, 0, 0);
s.knot.rotation.set(ctx.time * 0.11, ctx.time * 0.17, 0);
s.knot.updateMatrixWorld();
// Rays are cast in the knot's local space, so the BVH never needs rebuilding.
s.inv.copy(s.knot.matrixWorld).invert();
const N = Math.min(s.MAX, u.u_rays), E = 3, t = ctx.time;
s.colors[0].setRGB(...u.u_colorA, THREE.SRGBColorSpace);
s.colors[1].setRGB(...u.u_colorB, THREE.SRGBColorSpace);
s.colors[2].setRGB(...u.u_colorC, THREE.SRGBColorSpace);
let count = 0;
const t0 = performance.now();
for (let i = 0; i < N; i++) {
  // Three emitters circle the knot, each sweeping a cone of rays toward the middle.
  const e = i % E, a = t * 0.5 + e * Math.PI * 2 / E;
  const ox = 4 * Math.cos(a), oy = 1.6 * Math.sin(t * 0.7 + e * 2), oz = 4 * Math.sin(a);
  const r = u.u_spread * Math.sqrt(Math.random()), th = Math.random() * 6.2832;
  const tx = r * Math.cos(th) * Math.cos(a + 1.57), ty = r * Math.sin(th), tz = r * Math.cos(th) * Math.sin(a + 1.57);
  s.ray.origin.set(ox, oy, oz);
  s.ray.direction.set(tx - ox, ty - oy, tz - oz).normalize();
  s.ray.applyMatrix4(s.inv);
  const hit = s.bvh.raycastFirst(s.ray, THREE.FrontSide);  // hit.point is in the knot's space
  if (!hit) continue;
  // Back the point off the surface a little so the splat isn't hidden by the knot's depth.
  const p = s.tmp.copy(hit.point).applyMatrix4(s.knot.matrixWorld), c = s.colors[e];
  const dx = p.x - ox, dy = p.y - oy, dz = p.z - oz, L = Math.hypot(dx, dy, dz), f = 0.015 / L, tail = Math.min(1, u.u_tail / L);
  p.set(p.x - dx * f, p.y - dy * f, p.z - dz * f);
  // A streak of the beam just before the hit, fading in toward it.
  s.linePos.set([p.x - dx * tail, p.y - dy * tail, p.z - dz * tail, p.x, p.y, p.z], count * 6);
  const k = u.u_beam;
  s.lineCol.set([0, 0, 0, c.r * k, c.g * k, c.b * k], count * 6);
  const q = hit.point.addScaledVector(s.ray.direction, -0.012);
  s.hitPos.set([q.x, q.y, q.z], s.head * 3);
  s.hitCol.set([c.r, c.g, c.b], s.head * 3);
  s.head = (s.head + 1) % s.HITS;
  count++;
}
const ms = performance.now() - t0;
s.lines.geometry.setDrawRange(0, count * 2);
const fade = Math.pow(u.u_fade, ctx.dt * 60);
for (let i = 0; i < s.hitCol.length; i++) s.hitCol[i] *= fade;
for (const g of [s.lines.geometry, s.hits.geometry]) { g.attributes.position.needsUpdate = true; g.attributes.color.needsUpdate = true; }
s.renderer.resetState();
s.renderer.render(s.scene, s.camera);
ctx.publish("rays", N);
ctx.publish("hits", count);
ctx.publish("raycast ms", Math.round(ms * 10) / 10);
